export function resolveLocale(value: unknown): LocaleCode {
  const normalized = String(value ?? '').trim().toLowerCase().replaceAll('_', '-');
  const exact = localeCodes.find(code => ([code, ...localeMetadata[code].aliases] as string[]).some(alias => alias.trim().toLowerCase().replaceAll('_', '-') === normalized));
  if (exact) return exact;
  const base = normalized.split('-')[0];
  return localeCodes.find(code => code === base) ?? 'en';
}
export function isSupportedLocale(value: unknown): value is LocaleCode {
  return typeof value === 'string' && Object.hasOwn(localeMetadata, value);
}
